function Reports({ invoices = [], payments = [], subscribers = [], routers = [], bandwidthHistory = [], employees = [], tickets = [], money }) {
  const [section, setSection] = useState('financial'); const [range, setRange] = useState('this_month'); const [from, setFrom] = useState(''); const [to, setTo] = useState('');
  const now = new Date(); const start = range === 'today' ? new Date(now.getFullYear(), now.getMonth(), now.getDate()) : range === 'this_week' ? new Date(now.getTime() - 6 * 86400000) : range === 'this_year' ? new Date(now.getFullYear(), 0, 1) : range === 'custom' && from ? new Date(from) : new Date(now.getFullYear(), now.getMonth(), 1); const end = range === 'custom' && to ? new Date(`${to}T23:59:59`) : now; const inRange = (value) => { const date = new Date(value || 0); return date >= start && date <= end; }; const rangePayments = payments.filter((item) => inRange(item.paid_at || item.created_at)); const rangeInvoices = invoices.filter((item) => inRange(item.created_at || item.due_date)); const income = rangePayments.reduce((sum, item) => sum + Number(item.amount || 0), 0); const outstanding = rangeInvoices.filter((item) => item.status !== 'paid').reduce((sum, item) => sum + Number(item.amount || 0) - Number(item.paid_amount || 0), 0); const online = subscribers.filter((item) => item.is_online).length; const maxTraffic = Math.max(...bandwidthHistory.map((item) => Number(item.download_mbps || 0) + Number(item.upload_mbps || 0)), 1); const exportReport = () => { const rows = section === 'financial' ? [['Metric', 'Value'], ['Income', income], ['Outstanding', outstanding], ['Payments', rangePayments.length]] : section === 'network' ? [['Metric', 'Value'], ['Routers', routers.length], ['Online subscribers', online], ['Peak Mbps', maxTraffic]] : [['Employee', 'Assigned tickets', 'Completed', 'Open']]; const csv = rows.map((row) => row.join(',')).join('\n'); const blob = new Blob([csv], { type: 'text/csv' }); const url = URL.createObjectURL(blob); const link = document.createElement('a'); link.href = url; link.download = `nexa-${section}-report.csv`; link.click(); URL.revokeObjectURL(url); };
  const employeeRows = employees.map((employee) => { const assigned = tickets.filter((ticket) => Number(ticket.assigned_employee_id || ticket.assignedEmployeeId) === Number(employee.id)); return { ...employee, assigned: assigned.length, completed: assigned.filter((ticket) => ['closed', 'resolved', 'completed'].includes(String(ticket.status).toLowerCase())).length, open: assigned.filter((ticket) => !['closed', 'resolved', 'completed'].includes(String(ticket.status).toLowerCase())).length }; });
  const card = 'rounded-2xl border border-slate-100 bg-white shadow-sm'; return <div className="space-y-5"><section className="relative overflow-hidden rounded-2xl bg-gradient-to-br from-[#26006b] via-[#5600c6] to-[#8d2cff] p-6 text-white shadow-xl"><p className="text-[10px] font-black uppercase tracking-[.2em] text-violet-200">Business intelligence</p><h2 className="mt-2 text-3xl font-black">Reports</h2><p className="mt-2 max-w-xl text-sm text-violet-100">Understand collections, network health, and employee performance from one scoped workspace.</p><div className="mt-5 flex flex-wrap gap-2"><select value={range} onChange={(event) => setRange(event.target.value)} className="rounded-xl border border-white/20 bg-white/10 px-3 py-2 text-xs font-bold text-white outline-none"><option className="text-slate-900" value="today">Today</option><option className="text-slate-900" value="this_week">This week</option><option className="text-slate-900" value="this_month">This month</option><option className="text-slate-900" value="this_year">This year</option><option className="text-slate-900" value="custom">Custom range</option></select>{range === 'custom' && <><input type="date" value={from} onChange={(event) => setFrom(event.target.value)} className="rounded-xl px-3 py-2 text-xs text-slate-900" /><input type="date" value={to} onChange={(event) => setTo(event.target.value)} className="rounded-xl px-3 py-2 text-xs text-slate-900" /></>}<button onClick={exportReport} className="rounded-xl bg-emerald-400 px-4 py-2 text-xs font-black text-emerald-950">Export CSV</button></div></section><div className="grid grid-cols-3 gap-2"><button onClick={() => setSection('financial')} className={`rounded-xl px-3 py-3 text-xs font-black ${section === 'financial' ? 'bg-violet-600 text-white' : 'bg-white text-slate-500'}`}>Financial</button><button onClick={() => setSection('network')} className={`rounded-xl px-3 py-3 text-xs font-black ${section === 'network' ? 'bg-violet-600 text-white' : 'bg-white text-slate-500'}`}>Network</button><button onClick={() => setSection('employees')} className={`rounded-xl px-3 py-3 text-xs font-black ${section === 'employees' ? 'bg-violet-600 text-white' : 'bg-white text-slate-500'}`}>Employees</button></div>{section === 'financial' && <div className="grid gap-4 sm:grid-cols-3"><div className={`${card} p-5`}><p className="text-xs font-bold text-slate-400">Income</p><p className="mt-2 text-2xl font-black text-emerald-600">{money(income)}</p><p className="mt-1 text-xs text-slate-400">{rangePayments.length} payments</p></div><div className={`${card} p-5`}><p className="text-xs font-bold text-slate-400">Outstanding</p><p className="mt-2 text-2xl font-black text-orange-500">{money(outstanding)}</p><p className="mt-1 text-xs text-slate-400">{rangeInvoices.length} invoices</p></div><div className={`${card} p-5`}><p className="text-xs font-bold text-slate-400">Taxes</p><p className="mt-2 text-2xl font-black text-slate-300">Coming later</p><p className="mt-1 text-xs text-slate-400">KRA integration planned</p></div></div>}{section === 'network' && <div className="grid gap-4 sm:grid-cols-3"><div className={`${card} p-5`}><p className="text-xs font-bold text-slate-400">Routers monitored</p><p className="mt-2 text-2xl font-black">{routers.length}</p></div><div className={`${card} p-5`}><p className="text-xs font-bold text-slate-400">Online subscribers</p><p className="mt-2 text-2xl font-black text-emerald-600">{online}</p></div><div className={`${card} p-5`}><p className="text-xs font-bold text-slate-400">Peak traffic</p><p className="mt-2 text-2xl font-black text-violet-600">{maxTraffic.toFixed(1)} Mbps</p></div></div>}{section === 'employees' && <section className={`${card} overflow-hidden`}><div className="border-b border-slate-100 px-5 py-4"><h3 className="font-black">Employee performance</h3><p className="mt-1 text-xs text-slate-400">Task ownership, completion, and current workload</p></div>{employeeRows.length ? <div className="divide-y divide-slate-100">{employeeRows.map((employee) => <div key={employee.id} className="flex items-center justify-between gap-3 px-5 py-4"><div><p className="font-black">{employee.name}</p><p className="text-xs text-slate-400">{employee.role || 'Team member'}</p></div><div className="flex gap-3 text-right text-xs"><span><b className="block text-slate-900">{employee.assigned}</b><small className="text-slate-400">Assigned</small></span><span><b className="block text-emerald-600">{employee.completed}</b><small className="text-slate-400">Done</small></span><span><b className="block text-orange-500">{employee.open}</b><small className="text-slate-400">Open</small></span></div></div>)}</div> : <Empty title="No employee task data yet" text="Assign work through the employee task workflow to start measuring performance." />}</section>}</div>;
}
